<?php
namespace Azula\SmsStudio;

final class M2Screen
{
    public function register(): void
    {
        add_action('admin_menu',[$this,'menu']);add_action('admin_enqueue_scripts',[$this,'assets']);add_action('wp_ajax_azula_sms_m2',[M2Api::class,'ajax']);
        add_action('admin_post_azula_sms_export',[AudienceCsv::class,'download']);
    }
    public function menu(): void
    {
        $hook=add_menu_page('Azula SMS Studio','Azula SMS Studio','manage_options','azula-sms-studio',[$this,'screen'],'dashicons-format-chat',59);
        if($hook)add_action('load-'.$hook,[$this,'headers']);
        add_submenu_page('azula-sms-studio','SMS maintenance','Maintenance','manage_azula_sms_settings','azula-sms-maintenance',[$this,'maintenance']);
    }
    public function headers(): void { nocache_headers();header('Cache-Control: private, no-store, max-age=0');header('Referrer-Policy: no-referrer');header('X-Robots-Tag: noindex, nofollow'); }
    public function assets(string $hook): void
    {
        $assetVersion=AZULA_SMS_STUDIO_VERSION.(ScheduledCampaign::modern()?'-approve-once-1':'');
        if($hook!=='toplevel_page_azula-sms-studio'){if(M10::modern()&&in_array($_GET['page']??'', ['azula-sms-maintenance','azula-sms-phone-diagnostics'],true))wp_enqueue_script('azula-sms-forms',plugin_dir_url(AZULA_SMS_STUDIO_FILE).'assets/studio-forms.js',[],$assetVersion,true);return;}
        $url=plugin_dir_url(AZULA_SMS_STUDIO_FILE).'assets/';
        wp_enqueue_style('azula-sms-m2',$url.'studio.css',[],$assetVersion);
        wp_enqueue_script('azula-sms-m2',$url.'studio.js',[],$assetVersion,true);
        wp_enqueue_style('azula-sms-m6',$url.'studio-m6.css',['azula-sms-m2'],$assetVersion);
        wp_enqueue_style('azula-sms-flow',$url.'studio-flow.css',['azula-sms-m6'],$assetVersion);
        wp_enqueue_script('azula-sms-m6',$url.'studio-flow.js',['azula-sms-m2'],$assetVersion,true);
        if(M9Schema::modern()){wp_enqueue_script('azula-sms-m9',$url.'studio-m9.js',['azula-sms-m6'],$assetVersion,true);wp_enqueue_style('azula-sms-m9',$url.'studio-m9.css',['azula-sms-flow'],$assetVersion);}
        if(M91Campaign::modern())wp_enqueue_script('azula-sms-m91',$url.'studio-m91.js',['azula-sms-m9'],$assetVersion,true);
        if(M92Policy::modern())wp_enqueue_script('azula-sms-m92',$url.'studio-m92.js',['azula-sms-m91'],$assetVersion,true);
        if(RC2Audiences::modern())wp_enqueue_script('azula-sms-audiences',$url.'studio-audiences.js',['azula-sms-m92'],$assetVersion,true);
        if(M10::modern())wp_enqueue_script('azula-sms-m10',$url.'studio-m10.js',['azula-sms-audiences'],$assetVersion,true);
        if(M7Settings::modern())wp_enqueue_script('azula-sms-m7',$url.'studio-m7.js',['azula-sms-m6'],$assetVersion,true);
        wp_add_inline_script('azula-sms-m2','window.AzulaStudio='.wp_json_encode(['url'=>admin_url('admin-ajax.php'),'export_url'=>admin_url('admin-post.php'),'nonce'=>wp_create_nonce('azula_sms_m2'),'provider_admin'=>current_user_can('manage_azula_sms_settings'),'m5'=>false,'m6'=>true,'m61'=>true,'m8'=>M8Tokens::modern(),'m9'=>M9Schema::modern(),'m92'=>M92Policy::modern(),'rc1'=>RC1Status::modern(),'rc2'=>RC2Audiences::modern(),'m10'=>M10::modern(),'hotfix'=>MessageValidation::modern()]).';','before');
    }
    public function screen(): void
    {
        if(!current_user_can('manage_options') || !current_user_can('manage_azula_sms_campaigns') || !current_user_can('manage_woocommerce') || !current_user_can('edit_shop_orders')){wp_die('Not authorized.');return;}
        echo self::markup(true);
    }
    public function maintenance(): void
    {
        if(!current_user_can('manage_options') || !current_user_can('manage_azula_sms_settings')){wp_die('Not authorized.');return;}
        echo '<div class="wrap"><h1>SMS maintenance</h1><p>Sending is disabled. Customer data is never modified.</p>';
        foreach(['upgrade'=>'Upgrade SMS-owned schema','purge'=>'Purge expired SMS evidence'] as $op=>$label){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('azula_sms_m1');echo '<input type="hidden" name="action" value="azula_sms_m1"><input type="hidden" name="operation" value="'.$op.'"><button class="button">'.esc_html($label).'</button></form>';}
        if(current_user_can('manage_azula_sms_suppressions')){echo '<h2>Explicit SMS opt-out</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('azula_sms_m1');echo '<input type="hidden" name="action" value="azula_sms_m1"><input type="hidden" name="operation" value="suppress"><input name="phone" autocomplete="off" required aria-label="Phone"><select name="suppression_state"><option value="active">Record SMS opt-out</option><option value="revoked">Revoke under owner policy</option></select><button class="button">Save suppression</button></form>';}
        echo '</div>';
    }
